/**
 * Event Service Client for Expo/React Native
 * Fetches events from local API server (server-side Ticketmaster calls)
 * This avoids exposing API keys in the client
 * 
 * ARCHITECTURE:
 * - PRIMARY: Supabase (normalized, canonicalized events)
 * - DEBUG: Direct API (/debug-direct-events) - for development only
 * 
 * IMPORTANT: All production traffic goes through Supabase only.
 * The direct API endpoint is deprecated and only for debugging.
 */

// Local API server URL - MUST use host LAN IP for physical iPhone
// The server runs on the host machine and Expo Go on iPhone needs the host IP
const API_BASE_URL = 'http://192.168.68.101:8080';

// Feature flag: Enable fallback to direct API (development only!)
// Set to false in production - all traffic should go through Supabase
const USE_DIRECT_API_FALLBACK = false;

const TIMEOUT = 15000;

/**
 * Generic fetch wrapper
 */
async function fetchFromAPI(endpoint = '/supabase-events') {
  try {
    const response = await fetch(`${API_BASE_URL}${endpoint}`, {
      method: 'GET',
      headers: {
        'Accept': 'application/json',
        'Content-Type': 'application/json',
      },
    });

    if (!response.ok) {
      console.warn(`[EventService] API error: ${response.status}`);
      return { error: `HTTP ${response.status}` };
    }

    return await response.json();
  } catch (error) {
    console.warn(`[EventService] Network error: ${error.message}`);
    return { error: error.message };
  }
}

/**
 * Fetch events from Supabase (normalized storage)
 * This is the PRIMARY and ONLY source for events in production
 */
export async function fetchFromSupabase() {
  const data = await fetchFromAPI('/supabase-events');

  if (data.error || !data.events) {
    console.error('[EventService] Supabase fetch failed:', data.error);
    return {
      events: [],
      sources: [],
      metadata: {
        data_source: 'supabase',
        fallback_used: false,
        error: data.error || 'No events returned'
      }
    };
  }

  return {
    events: data.events || [],
    sources: data.sources || [],
    count: data.count || 0,
    metadata: {
      data_source: 'supabase',
      fallback_used: false,
      available_sources: data.sources || [],
      total_count: data.count || 0,
      last_ingested_at: data.last_ingested_at || null,
      ingestion_stats: data.ingestion_stats || null
    }
  };
}

/**
 * DEBUG ONLY: Fetch events directly from provider APIs
 * 
 * WARNING: This endpoint returns RAW, non-normalized data.
 * Do NOT use in production - data will not have canonical sources,
 * consistent schemas, or proper deduplication.
 */
export async function fetchDirectFromAPIs() {
  console.warn('[EventService] WARNING: Using deprecated direct API endpoint');

  const data = await fetchFromAPI('/debug-direct-events');

  if (data.error || !data.ticketmaster) {
    return {
      events: [],
      sources: [],
      metadata: {
        data_source: 'direct_api',
        fallback_used: true,
        warning: 'DEPRECATED: Raw data from provider APIs, not normalized'
      }
    };
  }

  const allEvents = [];

  if (data.ticketmaster?.events) {
    allEvents.push(...data.ticketmaster.events);
  }

  if (data.otherSources?.sources?.kulturhuset) {
    allEvents.push(...data.otherSources.sources.kulturhuset);
  }

  if (data.otherSources?.sources?.malmolive) {
    allEvents.push(...data.otherSources.sources.malmolive);
  }

  return {
    events: allEvents,
    sources: data.sources || [],
    count: allEvents.length,
    metadata: {
      data_source: 'direct_api',
      fallback_used: true,
      warning: 'DEPRECATED: Raw data from provider APIs, not normalized'
    }
  };
}

/**
 * Fetch events - Supabase only (production mode)
 * This is the standard function to use in the app
 */
export async function fetchEventsSupabaseOnly() {
  return fetchFromSupabase();
}

/**
 * Fetch events with fallback (development mode only)
 * WARNING: Only enabled when USE_DIRECT_API_FALLBACK=true
 */
export async function fetchEventsWithFallback() {
  // Try Supabase first (always)
  const supabaseData = await fetchFromSupabase();

  if (supabaseData.events.length > 0) {
    return supabaseData;
  }

  // Only use fallback if explicitly enabled
  if (USE_DIRECT_API_FALLBACK) {
    console.warn('[EventService] WARNING: Falling back to direct API (development only!)');
    return fetchDirectFromAPIs();
  }

  // No fallback - return empty with clear error
  return {
    events: [],
    sources: [],
    metadata: {
      data_source: 'supabase',
      fallback_used: false,
      error: 'No events in Supabase. Fallback disabled.',
      action_required: 'Run ingestion pipeline to populate Supabase'
    }
  };
}

/**
 * Legacy function - use fetchEventsSupabaseOnly() instead
 */
export async function fetchAllEventsViaServer() {
  return fetchEventsSupabaseOnly();
}

/**
 * Health check for API server and ingestion status
 */
export async function checkAPIHealth() {
  const data = await fetchFromAPI('/health');

  if (data.error) {
    return { 
      connected: false, 
      error: data.error 
    };
  }

  return {
    connected: true,
    status: data.status,
    ticketmasterKey: data.ticketmasterKey,
    supabase: data.supabase,
    ingestion: data.ingestion || null,
  };
}

// Export for use in App.js
export const fetchEvents = fetchEventsSupabaseOnly;
export const fetchEventsFromSupabase = fetchEventsSupabaseOnly; // Alias for clarity
export { API_BASE_URL, USE_DIRECT_API_FALLBACK };

